<template>
  <div class="lowcode-business-container">
    <el-page-header @back="$router.push('/')">
      <template #content>
        <span class="font-weight-bold">{{ appData?.name || '加载中...' }}</span>
      </template>
      <template #extra>
        <el-button type="primary" @click="showCreateDialog = true">
          <el-icon class="mr-1"><Plus /></el-icon> 新增申请
        </el-button>
      </template>
    </el-page-header>

    <!-- 实例列表 -->
    <el-card class="mt-6">
      <el-table :data="instances" stripe style="width: 100%" v-loading="loading">
        <el-table-column prop="id" label="单号" width="80" />
        <el-table-column label="提交时间" width="180">
          <template #default="{ row }">
            {{ new Date(row.created_at).toLocaleString() }}
          </template>
        </el-table-column>
        <el-table-column label="当前状态" width="120">
          <template #default="{ row }">
            <el-tag :type="getStatusType(row.status)">{{ getStatusText(row.status) }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column label="详情">
          <template #default="{ row }">
            <div class="instance-data-preview">
              <span v-for="(val, key) in row.data" :key="key" class="data-item">
                <strong>{{ getFieldLabel(key) }}:</strong> {{ val }}
              </span>
            </div>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="120" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" @click="viewDetail(row)">查看流程</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <!-- 新增申请弹窗 -->
    <el-dialog v-model="showCreateDialog" :title="'提交' + appData?.name" width="600px">
      <DynamicForm 
        v-if="showCreateDialog && appData"
        :appCode="appData.code"
        @success="handleCreateSuccess"
        @cancel="showCreateDialog = false"
      />
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, onMounted, reactive, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Plus } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import api from '@/api'
import DynamicForm from '@/components/DynamicForm.vue'

const route = useRoute()
const router = useRouter()
const loading = ref(false)
const showCreateDialog = ref(false)
const appData = ref(null)
const appFields = ref([])
const instances = ref([])
const currentUser = ref(null)

const fetchAppData = async () => {
  try {
    const res = await api.getLowCodeAppDetail(route.params.code)
    if (res.data && res.data.length > 0) {
      appData.value = res.data[0]
      // 提取字段配置仅用于预览列表中的 Label 转换
      if (appData.value.forms && appData.value.forms.length > 0) {
        appFields.value = appData.value.forms[0].fields
      }
      fetchInstances()
    }
  } catch (error) {
    ElMessage.error('加载应用配置失败')
  }
}

const fetchInstances = async () => {
  if (!appData.value) return
  loading.value = true
  try {
    const res = await api.getLowCodeInstances(appData.value.code, currentUser.value?.id)
    instances.value = res.data?.results || res.data || []
  } catch (error) {
    console.error(error)
  } finally {
    loading.value = false
  }
}

const getFieldLabel = (key) => {
  if (key === 'approver_id') return '审批老师'
  const field = appFields.value.find(f => f.field_name === key)
  return field ? field.field_label : key
}

const getStatusText = (status) => ({
  pending: '待审批',
  approved: '已批准',
  rejected: '已驳回',
  completed: '已完成',
  draft: '草稿'
}[status] || status)

const getStatusType = (status) => ({
  pending: 'warning',
  approved: 'success',
  rejected: 'danger',
  completed: 'info',
  draft: 'info'
}[status] || 'info')

const handleCreateSuccess = () => {
  showCreateDialog.value = false
  fetchInstances()
}

const viewDetail = (row) => {
  // 跳转到审批中心查看详情
  router.push('/approvals')
}

// 监听路由变化（比如从请假切换到采购）
watch(() => route.params.code, () => {
  fetchAppData()
})

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) currentUser.value = JSON.parse(userStr)
  fetchAppData()
})
</script>

<style scoped>
.lowcode-business-container { padding: 20px; }
.instance-data-preview { display: flex; flex-wrap: wrap; gap: 10px; }
.data-item { font-size: 13px; color: #666; background: #f0f2f5; padding: 2px 8px; border-radius: 4px; }
</style>
